/**
 * Backward-compat: 旧 banner-matcher.ts が参照するフラットな配列。
 * 各プログラムの primary バリアント（rectangle 優先、なければ最初の image variant、最終手段 text-link）を返す。
 */
export const BANNER_ENTRIES: BannerEntry[] = BANNER_CATALOG.map((p) => {
  const rect = p.variants.find((v) => v.size === 'rectangle' && v.image)
    ?? p.variants.find((v) => v.image)
    ?? p.variants[0];
  return {
    id: p.id,
    programId: p.programId,
    name: p.name,
    category: p.category,
    keywords: p.keywords,
    image: rect.image ?? '',
    imageWidth: rect.width ?? 0,
    imageHeight: rect.height ?? 0,
    a8url: rect.a8url,
  };
});
